comment on table erp.franchise_royalties is 'erp product data (generated by scripts/gen-erp.mjs). module: accounting';

create table erp.quality_audits (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default app.current_org_id() references core.organizations(id) on delete cascade,
  branch_id uuid default erp.my_branch_id(),
  framework text not null default 'internal' check (framework in ('sqaa', 'internal', 'safety', 'brand')),
  date date not null default current_date,
  auditor text,
  items jsonb not null default '[]'::jsonb,
  score numeric,
  status text not null default 'planned' check (status in ('planned', 'in_progress', 'closed')),
  evidence_notes text,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id)
);
create index quality_audits_branch on erp.quality_audits(org_id, branch_id);
create trigger trg_touch before update on erp.quality_audits for each row execute function app.touch_updated_at();
select app.apply_rls('erp', 'quality_audits', 'product', 'erp', 'setup');
comment on table erp.quality_audits is 'erp product data (generated by scripts/gen-erp.mjs). module: setup';

create table erp.disclosures (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default app.current_org_id() references core.organizations(id) on delete cascade,
  item text not null,
  value text,
  document_file_id uuid,
  updated_on date not null default current_date,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, document_file_id) references core.files(org_id, id) on delete set null (document_file_id)
);
create index disclosures_document_file_id on erp.disclosures(org_id, document_file_id);
create trigger trg_touch before update on erp.disclosures for each row execute function app.touch_updated_at();
select app.apply_rls('erp', 'disclosures', 'product', 'erp', 'setup');
create policy sel_members on erp.disclosures for select using (org_id = app.current_org_id() and app.user_has_product(org_id, 'erp'));
comment on table erp.disclosures is 'erp product data (generated by scripts/gen-erp.mjs). module: setup';
